# Rebuilds web/study-problems.js and re-checks every numeric answer key independently.
#   python build-study.py   (run from the repository root)
import json, math
P=[]
def add(id,subject,topic,title,statement,choices,answer,hint,solution):
    assert choices.count(answer)==1,(id,answer,choices)
    P.append(dict(id=id,subject=subject,topic=topic,title=title,statement=statement,choices=choices,answer=choices.index(answer),hint=hint,solution=solution))
C='Chem Olympiad'; A='AI Olympiad'
add('chem-01',C,'Stoichiometry','Limiting reactant','Aluminum reacts with chlorine: 2 Al + 3 Cl₂ → 2 AlCl₃. If 5.40 g of Al (26.98 g/mol) and 10.65 g of Cl₂ (70.90 g/mol) react completely, what mass of AlCl₃ (133.33 g/mol) forms?',['8.90 g','13.4 g','20.0 g','26.7 g'],'13.4 g','Convert both to moles, then divide each by its coefficient to find which runs out first.','Al: 5.40/26.98 = 0.200 mol. Cl₂: 10.65/70.90 = 0.150 mol. Per coefficient: 0.200/2 = 0.100 and 0.150/3 = 0.050, so Cl₂ is limiting. AlCl₃ formed = 0.1502 × (2/3) = 0.1001 mol, and 0.1001 × 133.33 = 13.4 g. Answer: B.')
add('chem-02',C,'Gases','Identify the gas','A gas has a density of 1.96 g/L at 0 °C and 1.00 atm. Which gas is it? (R = 0.08206 L·atm/mol·K)',['N₂','O₂','CO₂','SO₂'],'CO₂','Molar mass = dRT/P.','M = (1.96)(0.08206)(273.15)/1.00 = 43.9 g/mol, which matches CO₂ (44.0 g/mol). Answer: C.')
add('chem-03',C,'Thermochemistry','Heat of combustion','Standard enthalpies of formation (kJ/mol): CO₂(g) −393.5, H₂O(l) −285.8, C₂H₅OH(l) −277.7. What is ΔH° for C₂H₅OH(l) + 3 O₂(g) → 2 CO₂(g) + 3 H₂O(l)?',['−1366.7 kJ','−957.0 kJ','−401.6 kJ','+1366.7 kJ'],'−1366.7 kJ','ΔH° = Σ ΔHf(products) − Σ ΔHf(reactants). O₂ is an element in its standard state.','Products: 2(−393.5) + 3(−285.8) = −1644.4 kJ. Reactants: −277.7 + 0. ΔH° = −1644.4 − (−277.7) = −1366.7 kJ. Answer: A.')
add('chem-04',C,'Kinetics','First-order decay','A first-order reaction has a half-life of 20 minutes. What percent of the reactant remains after 60 minutes?',['6.25%','12.5%','25%','33%'],'12.5%','For first order, every half-life cuts the amount in half regardless of how much is left.','60 minutes is three half-lives, so (1/2)³ = 1/8 = 12.5% remains. Answer: B.')
add('chem-05',C,'Equilibrium','Dissociation of N₂O₄','For N₂O₄(g) ⇌ 2 NO₂(g), Kc = 0.20 at a certain temperature. A flask initially contains only 1.00 M N₂O₄. What is [NO₂] at equilibrium?',['0.20 M','0.40 M','0.45 M','0.80 M'],'0.40 M','Let x be the decrease in [N₂O₄]; then [NO₂] = 2x. Solve the quadratic.','(2x)²/(1.00 − x) = 0.20 gives 4x² + 0.20x − 0.20 = 0, so x = (−0.20 + √3.24)/8 = 0.200. [NO₂] = 2x = 0.40 M. Check: 0.16/0.80 = 0.20. Answer: B.')
add('chem-06',C,'Acids and bases','Weak acid pH','What is the pH of 0.10 M acetic acid? (Ka = 1.8 × 10⁻⁵)',['1.00','2.87','4.74','5.74'],'2.87','[H⁺] ≈ √(Ka·C) when dissociation is small.','[H⁺] = √(1.8×10⁻⁵ × 0.10) = 1.34×10⁻³ M, so pH = 2.87. (Only 1.3% dissociates, so the approximation holds.) Answer: B.')
add('chem-07',C,'Acids and bases','Half-neutralized','0.050 mol of NaOH is added to 1.0 L of 0.10 M acetic acid (Ka = 1.8 × 10⁻⁵). What is the pH? Assume no volume change.',['2.87','4.44','4.74','7.00'],'4.74','After the reaction, compare moles of acid left with moles of conjugate base formed.','NaOH converts 0.050 mol of acid to acetate, leaving 0.050 mol of each. With [HA] = [A⁻], pH = pKa = −log(1.8×10⁻⁵) = 4.74. Answer: C.')
add('chem-08',C,'Electrochemistry','Cell free energy','For Zn(s) + Cu²⁺(aq) → Zn²⁺(aq) + Cu(s), E°(Cu²⁺/Cu) = +0.34 V and E°(Zn²⁺/Zn) = −0.76 V. What is ΔG°? (F = 96,485 C/mol)',['−106 kJ','−212 kJ','−318 kJ','+212 kJ'],'−212 kJ','E°cell = E°cathode − E°anode, then ΔG° = −nFE°.','E°cell = 0.34 − (−0.76) = 1.10 V, and n = 2. ΔG° = −(2)(96,485)(1.10) = −212,000 J = −212 kJ. Answer: B.')
add('chem-09',C,'Bonding','Molecular polarity','Which molecule has a nonzero dipole moment?',['CO₂','BF₃','SF₄','XeF₄'],'SF₄','Find each shape with VSEPR and ask whether the bond dipoles cancel.','CO₂ is linear, BF₃ trigonal planar and XeF₄ square planar, so their bond dipoles cancel. SF₄ has five electron domains with one lone pair (see-saw), which does not cancel. Answer: C.')
add('chem-10',C,'Solubility','Common ion effect','Ksp of AgCl is 1.8 × 10⁻¹⁰. What is its molar solubility in 0.10 M NaCl?',['1.3 × 10⁻⁵ M','1.8 × 10⁻⁹ M','1.8 × 10⁻¹⁰ M','1.8 × 10⁻¹¹ M'],'1.8 × 10⁻⁹ M','[Cl⁻] is essentially fixed at 0.10 M by the NaCl.','Ksp = [Ag⁺][Cl⁻] = s(0.10), so s = 1.8×10⁻¹⁰/0.10 = 1.8×10⁻⁹ M. (In pure water it would be 1.3×10⁻⁵ M.) Answer: B.')
add('chem-11',C,'Organic','Alcohol isomers','How many constitutional isomers with the formula C₄H₁₀O are alcohols?',['2','3','4','5'],'4','Draw the two butane skeletons and place the OH on each distinct carbon.','Straight chain: 1-butanol and 2-butanol. Branched chain: 2-methyl-1-propanol and 2-methyl-2-propanol. That is 4 (the other C₄H₁₀O isomers are ethers). Answer: C.')
add('chem-12',C,'Solutions','Freezing point','What is the freezing point of a 0.100 m aqueous CaCl₂ solution, assuming complete dissociation? (Kf = 1.86 °C/m)',['−0.186 °C','−0.372 °C','−0.558 °C','−0.744 °C'],'−0.558 °C','ΔTf = i·Kf·m. Count the ions per formula unit.','CaCl₂ gives 3 ions, so ΔTf = (3)(1.86)(0.100) = 0.558 °C and the solution freezes at −0.558 °C. Answer: C.')
add('ai-01',A,'Optimization','One gradient step','Minimize f(w) = (w − 3)² with gradient descent, starting at w = 0 with learning rate 0.1. What is w after one step?',['0.3','0.6','1.2','3.0'],'0.6','w ← w − η·f′(w).','f′(w) = 2(w − 3), so f′(0) = −6. w = 0 − 0.1(−6) = 0.6. Answer: B.')
add('ai-02',A,'Neural networks','Sigmoid slope','For the sigmoid σ(x) = 1/(1 + e⁻ˣ), what is σ′(0)?',['0','0.25','0.5','1'],'0.25','σ′(x) = σ(x)(1 − σ(x)).','σ(0) = 0.5, so σ′(0) = 0.5 × 0.5 = 0.25. This is the largest the slope ever gets, which is one reason deep sigmoid networks suffer vanishing gradients. Answer: B.')
add('ai-03',A,'Neural networks','Softmax','A classifier outputs logits (0, ln 3) for two classes. What probability does softmax give the second class?',['0.25','0.50','0.67','0.75'],'0.75','Exponentiate each logit, then normalize.','e⁰ = 1 and e^(ln 3) = 3, so the probabilities are 1/4 and 3/4. Answer: D.')
add('ai-04',A,'Convolutional networks','Output size','A 32×32 image passes through a convolution with a 5×5 kernel, stride 1 and no padding. What is the spatial size of the output?',['27×27','28×28','30×30','32×32'],'28×28','Output = (input − kernel + 2·padding)/stride + 1.','(32 − 5 + 0)/1 + 1 = 28, so 28×28. Padding of 2 would keep it at 32×32. Answer: B.')
add('ai-05',A,'Neural networks','Counting parameters','How many trainable parameters does a fully connected layer with 100 inputs and 10 outputs have, including biases?',['110','1000','1010','1100'],'1010','One weight per input-output pair, plus one bias per output.','Weights: 100 × 10 = 1000. Biases: 10. Total 1010. Answer: C.')
add('ai-06',A,'Evaluation','F1 score','A classifier produces 30 true positives, 10 false positives and 20 false negatives. What is its F1 score (to three decimals)?',['0.600','0.667','0.675','0.750'],'0.667','F1 is the harmonic mean of precision and recall.','Precision = 30/40 = 0.75. Recall = 30/50 = 0.60. F1 = 2(0.75)(0.60)/(0.75 + 0.60) = 0.667. Answer: B.')
add('ai-07',A,'Generalization','Reading the curves','A model reaches 99% training accuracy but 70% validation accuracy. Which change is most likely to help?',['Train for more epochs','Add more layers','Add regularization or more training data','Raise the learning rate'],'Add regularization or more training data','A large gap between training and validation accuracy has a name.','The gap means the model is overfitting: it has memorized the training set. Regularization (weight decay, dropout, early stopping) or more data reduces variance; more capacity or more epochs makes it worse. Answer: C.')
add('ai-08',A,'NumPy','Broadcasting','In NumPy, a has shape (3, 1) and b has shape (1, 4). What is the shape of a + b?',['(3, 4)','(4, 3)','(3, 1, 4)','It raises an error'],'(3, 4)','Compare the shapes dimension by dimension; a dimension of size 1 stretches to match.','Dimension 0: 3 vs 1 → 3. Dimension 1: 1 vs 4 → 4. The result has shape (3, 4). Answer: A.')
add('ai-09',A,'Loss functions','Cross-entropy','A model assigns probability 0.5 to the correct class. What is the cross-entropy loss for that example, using natural logs?',['0.301','0.500','0.693','1.000'],'0.693','Loss = −ln(probability of the correct class).','−ln(0.5) = ln 2 = 0.693. Answer: C.')
add('ai-10',A,'Classical ML','Nearest neighbours','Training points on a line: x = 1 (class A), 2 (A), 4 (B), 5 (B), 6 (B). Using 3-nearest-neighbours, what class is predicted for x = 3.4, and how many of the 3 neighbours agree?',['A, with 2 of 3','A, with 3 of 3','B, with 2 of 3','B, with 3 of 3'],'B, with 2 of 3','List the distance from 3.4 to every training point and take the three smallest.','Distances: 2.4, 1.4, 0.6, 1.6, 2.6. The three nearest are x = 4 (B), x = 2 (A) and x = 5 (B), so the vote is B, 2 to 1. Answer: C.')
add('ai-11',A,'Transformers','Attention cost','How does the cost of standard self-attention grow with sequence length n?',['O(log n)','O(n)','O(n log n)','O(n²)'],'O(n²)','Every token attends to every token.','Self-attention computes a score for each pair of positions, an n × n matrix, so time and memory grow as O(n²). This is why long contexts are expensive. Answer: D.')
add('ai-12',A,'Linear algebra','Eigenvalues','What are the eigenvalues of the matrix [[2, 1], [1, 2]]?',['1 and 2','1 and 3','2 and 2','0 and 4'],'1 and 3','Solve det(A − λI) = 0, or use trace and determinant.','Trace = 4 and determinant = 3, so λ² − 4λ + 3 = 0 and λ = 1 or 3. Eigenvectors are (1, −1) and (1, 1). Answer: B.')
# ---- independent numeric checks ----
V={}
V['chem-01']=min(5.40/26.98/2,10.65/70.90/3)*2*133.33
assert abs(1.96*0.08206*273.15-44.01)<0.3  # CO2, far from 28/32/64
V['chem-03']=2*-393.5+3*-285.8+277.7
V['chem-04']=100*0.5**(60/20)
x=(-0.2+math.sqrt(0.04+3.2))/8;V['chem-05']=2*x
V['chem-06']=-math.log10(math.sqrt(1.8e-5*0.10))
V['chem-07']=-math.log10(1.8e-5)
V['chem-08']=-2*96485*1.10/1000
V['chem-10']=1.8e-10/0.10
V['chem-12']=-3*1.86*0.100
V['ai-01']=0-0.1*2*(0-3); V['ai-02']=0.25; V['ai-03']=3/4; V['ai-05']=100*10+10
V['ai-06']=2*.75*.6/(.75+.6); V['ai-09']=math.log(2)
import re
def num(s):
    s=s.replace(' ','').replace('−','-').replace('×10','e')
    for a,b in zip('⁰¹²³⁴⁵⁶⁷⁸⁹⁻','0123456789-'): s=s.replace(a,b)
    m=re.match(r'[+-]?[\d.]+(e-?\d+)?',s.replace('×10','e')); return float(m[0])
for p in P:
    if p['id'] in V:
        got=num(p['choices'][p['answer']]); want=V[p['id']]; assert abs(got-want)<=max(0.012*abs(want),0.006),(p['id'],got,want)
        others=[num(c) for i,c in enumerate(p['choices']) if i!=p['answer']]; assert all(abs(o-want)>abs(got-want) for o in others),p['id']
print(len(P),'problems; numeric keys verified:',len(V)); print({k:round(v,4) for k,v in V.items()})
TOPICS={C:['Stoichiometry and limiting reactants','Gas laws and kinetic theory','Thermochemistry and Hess’s law','Kinetics: rate laws, half-lives, mechanisms','Equilibrium, Ksp and Le Châtelier','Acids, bases, buffers and titrations','Electrochemistry and redox','Atomic structure, periodic trends and bonding','Descriptive and laboratory chemistry','Organic basics: functional groups and isomers'],
 A:['Python and NumPy fluency','Linear algebra: vectors, matrices, eigenvalues','Calculus and probability for ML','Classical ML: regression, trees, k-NN, clustering','Evaluation: metrics, validation, overfitting','Neural networks and backpropagation','Convolutional networks for images','Sequence models, attention and transformers','Training practice: optimizers, regularization, debugging']}
open('web/study-problems.js','w',encoding='utf-8').write('// Original study questions in the style of the Chemistry Olympiad and AI Olympiad exams. Not official material.\nwindow.STUDY_TOPICS='+json.dumps(TOPICS,ensure_ascii=False)+';\nwindow.STUDY_PROBLEMS='+json.dumps(P,ensure_ascii=False,indent=1)+';\n')
